const TILE_OPEN = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"-20 -20 120 130\" overflow=\"visible\" style=\"overflow:visible\" role=\"img\" aria-label=\"Letter tile %L%\">";
/** A letter tile in one of its states. Letters a to z (lowercase); anything else gives a blank tile. */
export function tileSvg(letter: string, state: TileState = 'resting'): string {
  const l = letter.toLowerCase();
  return TILE_OPEN.replace('%L%', l) + TILE_TPL[state].replace('%G%', GLYPHS[l] ?? '') + '</svg>';
}

